{
  "name": "@paulirish/agents",
  "version": "0.1.0",
  "description": "A monorepo for Paul Irish's Gemini skills and CLI agents.",
  "type": "module",
  "private": true,
  "bin": {
    "heap-snapshot": "./skills/heap-snapshot-inspection/heap-snapshot-cli/bin/heap-snapshot.js"
  },
  "engines": {
    "node": ">=24.11.0"
  },
  "scripts": {
    "typecheck": "tsc --noEmit",
    "test:distill": "node --test \"skills/distill-page/test/!(*cdp).test.ts\" && node --test skills/distill-page/test/cdp.test.ts && node --test skills/distill-page/test/turndown-cdp.test.ts",
    "test:compatibility": "RUN_ALL_TURNDOWN_TESTS=1 node --test skills/distill-page/test/turndown-cdp.test.ts",
    "test": "pnpm run test:distill && pnpm --filter !turndown -r run test",
    "preflight": "pnpm typecheck && pnpm test"
  },
  "dependencies": {
    "@bufbuild/protobuf": "2.12.1",
    "heap-snapshot-toolkit": "^1.1.3",
    "markpaste": "^0.0.6",
    "playwright": "^1.61.1"
  },
  "devDependencies": {
    "@types/node": "^25.9.5",
    "@types/turndown": "^5.0.6",
    "turndown": "^7.2.4",
    "turndown-plugin-gfm": "^1.0.2",
    "typescript": "^5.8.2"
  }
}

{
  "name": "@paulirish/heap-snapshot-cli",
  "version": "0.1.0",
  "description": "A CLI to explore Chromium heap snapshots.",
  "type": "module",
  "bin": {
    "heap-snapshot": "./bin/heap-snapshot.js"
  },
  "engines": {
    "node": ">=24.11.0"
  },
  "scripts": {
    "test": "node --test test/**/*.test.js",
    "typecheck": "tsc --noEmit"
  },
  "dependencies": {
    "heap-snapshot-toolkit": "^1.1.3"
  },
  "devDependencies": {
    "typescript": "^5.0.0"
  }
}

module.exports = {

  "extends": [
    "eslint:recommended",
    // "plugin:import/errors",
    // "plugin:import/warnings",
    // "kentcdodds/possible-errors",
    // "kentcdodds/best-practices",
    // "kentcdodds/es6/possible-errors",
    // "kentcdodds/import",
    // "plugin:promise/recommended",
    // "xo/esnext",
    // "plugin:unicorn/recommended",
    // "google"
  ],
  "plugins": [
    // "unicorn",
    // "import",
    // "json",
    // "eslint-comments",
    // "optimize-regex",
    // "promise"
  ],

  "env": {
    "browser": true,
    "es6": true,
    "node": true
  },

  "rules": {
    "no-console": "off",
    "indent": ["error", 2, {
      "SwitchCase": 1,
      "VariableDeclarator": 2
    }],
    "max-len": ["error", 120, {
      "ignoreComments": true,
      "ignoreUrls": true,
      "tabWidth": 2
    }],
    "no-unused-vars": ["error", {
      "vars": "all",
      "args": "after-used",
      "argsIgnorePattern": "(^reject$|^_$)",
      "varsIgnorePattern": "(^_$)"
    }],

    // "eslint-comments/disable-enable-pair": "error",
    // "eslint-comments/no-duplicate-disable": "error",
    // "eslint-comments/no-unlimited-disable": "error",
    // "eslint-comments/no-unused-disable": "error",
    // "eslint-comments/no-unused-enable": "error",

    // "optimize-regex/optimize-regex": "warn",

    "valid-jsdoc": "off", // it's wrong pretty often
    "comma-dangle": "off",
    "strict": "off",
    "curly": "off",
    "arrow-parens": ["error", "as-needed"],
    "no-return-assign": "off",
    // "unicorn/prefer-type-error": "off",
    "require-jsdoc": "off",
    "no-implicit-coercion": "off",
    "capitalized-comments": "warn"

    }
};

