{
  "name": "statikk",
  "version": "3.1.0",
  "description": "Simple, secure static file server – serve any directory over HTTP",
  "homepage": "https://github.com/paulirish/statikk/",
  "author": "David Hong <davidhong.code@gmail.com>, Paul Irish",
  "keywords": [
    "statikk",
    "statik",
    "static",
    "server",
    "development",
    "devserver"
  ],
  "repository": {
    "type": "git",
    "url": "git+https://github.com/paulirish/statikk.git"
  },
  "type": "module",
  "bugs": {
    "url": "https://github.com/paulirish/statikk/issues"
  },
  "scripts": {
    "build": "tsc -p tsconfig.build.json",
    "test": "node --test test/*.test.js",
    "typecheck": "tsc --noEmit",
    "prepare": "tsc -p tsconfig.build.json",
    "preflight": "pnpm run typecheck && pnpm run test"
  },
  "dependencies": {
    "compression": "^1.7.4",
    "connect": "~3.7.0",
    "cors": "^2.8.5",
    "serve-static": "^2.2.1"
  },
  "types": "./types/index.d.ts",
  "exports": {
    "types": "./types/index.d.ts",
    "default": "./index.js"
  },
  "files": [
    "index.js",
    "bin",
    "lib",
    "types"
  ],
  "engines": {
    "node": ">=18"
  },
  "bin": {
    "statikk": "bin/statikk"
  },
  "license": "MIT",
  "devDependencies": {
    "@types/compression": "^1.8.1",
    "@types/connect": "^3.4.38",
    "@types/cors": "^2.8.19",
    "@types/node": "^25.5.0",
    "@types/serve-static": "^2.2.0",
    "typescript": "^6.0.2"
  }
}

