// rollup.config.js
import resolve from 'rollup-plugin-node-resolve';
import commonjs from 'rollup-plugin-commonjs';
import buble from '@rollup/plugin-buble';
import { visualizer } from 'rollup-plugin-visualizer';


export default {
  input: 'script/main.js',
  output: {
    file: 'calc.js',
    format: 'es',
    sourcemap: true,
  },
  plugins: [
    resolve(),
    buble({
      jsx: 'h',
      objectAssign: 'Object.assign',
      target: { chrome: 71, safari: 11.1, firefox: 64 }, // roughly disable ES feature transpilation
		}),
    commonjs(),
    visualizer(), // build and view stats.html
  ]
};

{
  "name": "markpaste",
  "version": "0.0.6",
  "description": "HTML and Markdown, perfected for pasting into documents, emails, and more. So isomorphic. lol.",
  "main": "src/index.js",
  "bin": {
    "markpaste": "bin/markpaste"
  },
  "scripts": {
    "start": "npx statikk --port 7025",
    "typecheck": "tsc --noEmit",
    "format": "prettier --write \"**/*.{js,ts,json,md}\"",
    "test": "pnpm run typecheck && pnpm run test:node && pnpm run test:web",
    "test:web": "playwright test",
    "test:node": "node --test test/node/**/*.test.js",
    "build:app": "./scripts/build-app.sh",
    "install:app": "pnpm run build:app && rm -rf /Applications/MarkPaste.app && mv dist/MarkPaste.app /Applications/ && mdimport /Applications/MarkPaste.app"
  },
  "packageManager": "pnpm@10.22.0",
  "keywords": [
    "markdown",
    "html",
    "clipboard",
    "isomorphic"
  ],
  "author": "Paul Irish <npm@paul.irish>",
  "repository": {
    "type": "git",
    "url": "https://github.com/paulirish/markpaste"
  },
  "license": "Apache-2.0",
  "type": "module",
  "devDependencies": {
    "@playwright/test": "^1.57.0",
    "@types/prismjs": "^1.26.5",
    "@types/turndown": "^5.0.6",
    "prettier": "^3.7.3",
    "statikk": "^2.2.2",
    "typed-query-selector": "^2.12.0",
    "typescript": "^5.9.3"
  },
  "dependencies": {
    "@bjorn3/browser_wasi_shim": "^0.4.2",
    "@types/node": "^25.0.3",
    "linkedom": "^0.18.12",
    "marked": "^17.0.1",
    "turndown": "^7.2.2",
    "turndown-plugin-gfm": "^1.0.2"
  },
  "pnpm": {
    "overrides": {
      "markpaste": "link:"
    }
  }
}

import {defineConfig, devices} from '@playwright/test';

export default defineConfig({
  testDir: './test',
  fullyParallel: true,
  forbidOnly: !!process.env.CI,
  retries: process.env.CI ? 2 : 0,
  workers: process.env.CI ? 1 : undefined,
  reporter: 'list',
  use: {
    trace: 'on-first-retry',
  },
  projects: [
    {
      name: 'chromium',
      use: {...devices['Desktop Chrome']},
    },
  ],
  webServer: {
    command: 'npx http-server -p 7025',
    url: 'http://127.0.0.1:7025',
    reuseExistingServer: !process.env.CI,
  },
});

/**
 * @see https://prettier.io/docs/configuration
 * @type {import("prettier").Config}
 */
const config = {
  printWidth: 160,
  tabWidth: 2,
  singleQuote: true,
  trailingComma: 'es5',
  bracketSpacing: false,
  arrowParens: 'avoid',
};

export default config;

